// Probability points and normal quantile-quantile coordinates: R's ppoints, qqnorm (with plot.it = FALSE) and the
// line of qqline.
//
// Written for rStats.js to reproduce R's documented behaviour and output (experiments/plot121-log.md, experiments 1
// and 2): ppoints(n, a) = (i - a) / (n + 1 - 2a), a = 3/8 for n <= 10 else 1/2; qqnorm puts qnorm(ppoints(n)) at the
// ranks of the values (ties in order of appearance); qqline passes through the quartiles.
import { qnorm } from "../distributions/normal.js";
import { quantile } from "./quantile.js";
// Generated by `node scripts/option-keys.mjs --write` from the option types; do not edit (begin)
import { checkOptions } from "../internal/checkOptions.js";
const PPOINTS_KEYS = ["a"];
const QQLINE_KEYS = ["probs", "qtype", "distribution", "datax"];
/**
 * The probability points (i - a) / (n + 1 - 2a), i = 1, ..., n, for Q-Q plots. Equivalent to R's `ppoints()`. `n` is
 * the count, or an array whose length is the count (R's vector argument).
 *
 * @example
 * ```ts
 * ppoints(3); // [0.19230769230769232, 0.5, 0.8076923076923077]
 * ```
 *
 * @throws RangeError for a count that is negative or not finite.
 * @category Descriptive statistics
 */
export function ppoints(n, options = {}) {
    checkOptions(options, PPOINTS_KEYS, "ppoints"); // generated: option-keys.mjs
    const count = typeof n === "number" ? n : n.length;
    if (!Number.isFinite(count) || count < 0)
        throw new RangeError("'n' must be a non-negative number");
    const a = options.a ?? (count <= 10 ? 3 / 8 : 1 / 2);
    // as R: the points are i = 1, 2, ... up to n (a fractional n gives floor(n) of them) but the denominator uses n
    // itself; with n = 1 and a = 1 the point is 0 / 0 = NaN
    const k = Math.floor(count);
    return Array.from({ length: k }, (_, i) => (i + 1 - a) / (count + 1 - 2 * a));
}
/**
 * The coordinates of a normal quantile-quantile plot: for each value, the normal quantile of its plotting position.
 * Equivalent to R's `qqnorm(y, plot.it = FALSE)`. Missing values (NaN) keep their place with x = NaN and are not
 * counted; infinite values are ranked as the extremes.
 *
 * @example
 * ```ts
 * qqnorm([3.1, 1.2, 5.5]).x; // [0, -0.8694237732888861, 0.8694237732888861]
 * ```
 *
 * @throws RangeError when there is no value that is not missing.
 * @category Descriptive statistics
 */
export function qqnorm(y) {
    const v = Array.from(y);
    const idx = v.flatMap((t, i) => (Number.isNaN(t) ? [] : [i]));
    if (idx.length === 0)
        throw new RangeError("y is empty or has only NAs");
    const p = ppoints(idx.length).map((q) => qnorm(q));
    // a stable order: equal values take their positions in order of appearance (as R's order)
    idx.sort((i, j) => v[i] - v[j] || i - j);
    const x = v.map(() => NaN);
    idx.forEach((i, r) => {
        x[i] = p[r];
    });
    return { x, y: v };
}
/**
 * The line of a Q-Q plot through two quantiles (the quartiles by default) of the data and of the reference
 * distribution. Equivalent to R's `qqline()`. R draws the line and returns nothing; here its intercept and slope.
 * Missing values are ignored.
 *
 * @example
 * ```ts
 * const { intercept, slope } = qqline([3.1, 1.2, 5.5, 1.2, 9.0]);
 * ```
 *
 * @throws RangeError when there is no value that is not missing, or for probabilities outside [0, 1].
 * @category Descriptive statistics
 */
export function qqline(y, options = {}) {
    checkOptions(options, QQLINE_KEYS, "qqline"); // generated: option-keys.mjs
    const v = Array.from(y).filter((t) => !Number.isNaN(t));
    if (v.length === 0)
        throw new RangeError("y is empty or has only NAs");
    const probs = options.probs ?? [0.25, 0.75];
    if (probs.length !== 2 || !probs.every((p) => p >= 0 && p <= 1))
        throw new RangeError("'probs' must be two probabilities in [0, 1]");
    const dist = options.distribution ?? ((p) => qnorm(p));
    let [y1, y2] = quantile(v, probs, { type: options.qtype ?? 7 });
    let [x1, x2] = [dist(probs[0]), dist(probs[1])];
    if (options.datax ?? false)
        [x1, x2, y1, y2] = [y1, y2, x1, x2];
    const slope = (y2 - y1) / (x2 - x1);
    return { intercept: y1 - slope * x1, slope };
}
